mapper.select:
select t.*, COALESCE(t1.position_batch_intact_num,0) as positionBatchIntactNum, COALESCE(t1.position_batch_damage_num,0) as positionBatchDamageNum, t1.remark from ${positionStockBatchTableName} t left join (select * from ${stockCheckPositionBatchRecordTableName} where check_version = #{requestData.checkVersion}) t1 on t.batch_code = t1.batch_code where t.enterprise_code = #{enterpriseCode} and t.product_or_part = #{requestData.productOrPart} and t.delete_flag = false AND ( (t.batch != '系统导入' AND t.position_stock_batch_num > 0) OR -- (t.batch = '系统导入' AND t.position_stock_batch_num > 0) (t.batch = '系统导入' AND t.position_stock_batch_num >= 0) ) and t.position_code in
#{positionCode}
order by t.create_time asc ,t.id asc
